import { APIRequestContext, APIResponse } from '@playwright/test';

/**
 * Interface representing Product structure from Astronomy Shop API.
 */
export interface Product {
  id: string;
  name: string;
  description: string;
  picture: string;
  priceUsd: {
    currencyCode: string;
    units: number;
    nanos: number;
  };
  categories: string[];
}

/**
 * Interface representing a Cart Item from Astronomy Shop API.
 */
export interface CartItem {
  productId: string;
  quantity: number;
}

/**
 * Interface representing the Cart response structure.
 */
export interface CartResponse {
  userId: string;
  items: Array<{
    productId: string;
    quantity: number;
    product?: Product;
  }>;
}

/**
 * Interface representing Address for checkout.
 */
export interface Address {
  streetAddress: string;
  city: string;
  state: string;
  country: string;
  zipCode: string;
}

/**
 * Interface representing Credit Card details.
 */
export interface CreditCard {
  creditCardNumber: string;
  creditCardCvv: string;
  creditCardExpirationMonth: number;
  creditCardExpirationYear: number;
}

/**
 * Interface representing Checkout Order request payload.
 */
export interface PlaceOrderRequest {
  userId: string;
  email: string;
  address: Address;
  creditCard: CreditCard;
  userCurrency: string;
}

/**
 * High-quality client wrapper for interacting with the OpenTelemetry Astronomy Shop REST API.
 */
export class ApiClient {
  constructor(private request: APIRequestContext) {}

  /**
   * Fetch all products from the catalog.
   */
  async getProducts(currencyCode = 'USD'): Promise<APIResponse> {
    return this.request.get('/api/products', {
      params: { currencyCode },
    });
  }

  /**
   * Fetch a single product by ID.
   */
  async getProductById(productId: string, currencyCode = 'USD'): Promise<APIResponse> {
    return this.request.get(`/api/products/${productId}`, {
      params: { currencyCode },
    });
  }

  /**
   * Fetch the current cart for a user/session.
   */
  async getCart(sessionId: string, currencyCode = 'USD'): Promise<APIResponse> {
    return this.request.get('/api/cart', {
      params: {
        sessionId,
        currencyCode,
      },
    });
  }

  /**
   * Add a product item to the user's cart.
   */
  async addItemToCart(
    userId: string,
    productId: string,
    quantity: number,
    currencyCode = 'USD'
  ): Promise<APIResponse> {
    return this.request.post('/api/cart', {
      params: { currencyCode },
      data: {
        userId,
        item: {
          productId,
          quantity,
        },
      },
    });
  }

  /**
   * Clear all items in the user's cart.
   */
  async emptyCart(userId: string): Promise<APIResponse> {
    return this.request.delete('/api/cart', {
      data: { userId },
    });
  }

  /**
   * Submit an order for checkout.
   */
  async placeOrder(order: PlaceOrderRequest, currencyCode = 'USD'): Promise<APIResponse> {
    return this.request.post('/api/checkout', {
      params: { currencyCode },
      data: order,
    });
  }
}

import { test, expect } from '@playwright/test';
import { ApiClient } from '../../helpers/api_client';

test.describe('Product Catalog API', () => {
  let apiClient: ApiClient;

  test.beforeEach(({ request }) => {
    apiClient = new ApiClient(request);
  });

  test('Validate product catalog list response structure and values', async () => {
    const response = await apiClient.getProducts('USD');
    expect(response.status()).toBe(200);

    const products = await response.json();
    expect(Array.isArray(products)).toBe(true);
    expect(products.length).toBeGreaterThan(0);

    // Validate the structure of the first product
    const product = products[0];
    expect(product).toHaveProperty('id');
    expect(product).toHaveProperty('name');
    expect(product).toHaveProperty('description');
    expect(product).toHaveProperty('picture');
    expect(product).toHaveProperty('categories');
    expect(product).toHaveProperty('priceUsd');

    expect(typeof product.id).toBe('string');
    expect(typeof product.name).toBe('string');
    expect(typeof product.description).toBe('string');
    expect(typeof product.picture).toBe('string');
    expect(Array.isArray(product.categories)).toBe(true);

    const price = product.priceUsd;
    expect(price).toHaveProperty('currencyCode');
    expect(price).toHaveProperty('units');
    expect(price).toHaveProperty('nanos');
    expect(typeof price.currencyCode).toBe('string');
    expect(typeof price.units).toBe('number');
    expect(typeof price.nanos).toBe('number');
  });

  test('Validate single product retrieval by ID', async () => {
    // Get all products first to find a valid ID
    const listResponse = await apiClient.getProducts('USD');
    const products = await listResponse.json();
    const targetProduct = products[0];

    // Fetch details for the specific product ID
    const singleResponse = await apiClient.getProductById(targetProduct.id, 'USD');
    expect(singleResponse.status()).toBe(200);

    const product = await singleResponse.json();
    expect(product.id).toBe(targetProduct.id);
    expect(product.name).toBe(targetProduct.name);
    expect(product.description).toBe(targetProduct.description);
    expect(product.picture).toBe(targetProduct.picture);
    expect(product.priceUsd.units).toBe(targetProduct.priceUsd.units);
    expect(product.priceUsd.nanos).toBe(targetProduct.priceUsd.nanos);
  });
});

