import { test, expect } from '@playwright/test';

test.describe('Cart UI Verification', () => {
  test.beforeEach(async ({ page }) => {
    // Go to storefront homepage
    await page.goto('/');
  });

  test('Add product to cart and verify cart badge update', async ({ page }) => {
    // 1. Identify and click the first product
    const firstProductLink = page.locator('[data-cy="product-card"]').first();
    await expect(firstProductLink).toBeVisible();

    // Get product title on homepage to cross-reference later
    const expectedTitle = await firstProductLink.locator('h3, p, div').first().textContent();
    await firstProductLink.click();

    // 2. We should now be on the product detail page (PDP)
    await expect(page).toHaveURL(/\/product\/.+/);

    // Get the product title on PDP to ensure we are on the correct page
    const pdpTitle = await page.locator('[data-cy="product-name"]').first().textContent();
    if (expectedTitle && pdpTitle) {
      expect(pdpTitle.trim().toLowerCase()).toContain(expectedTitle.trim().substring(0, 10).toLowerCase());
    }

    // Locate quantity select and select quantity '3'
    const quantitySelect = page.locator('select[data-cy="product-quantity"]').first();
    await quantitySelect.selectOption({ label: '3' });

    // Click "Add To Cart"
    const addToCartBtn = page.locator('[data-cy="product-add-to-cart"]');
    await expect(addToCartBtn).toBeVisible();
    await addToCartBtn.click();

    // 3. Verify that the browser redirects to the cart page
    await expect(page).toHaveURL(/\/cart/);

    // Verify that the cart badge updates to reflect the added quantity '3'
    const cartBadge = page.locator('[data-cy="cart-item-count"]').first();
    await expect(cartBadge).toHaveText('3');
  });

  test('Verify cart calculations, subtotal, and empty cart functionality', async ({ page }) => {
    // 1. Click first product and navigate to PDP
    await page.locator('[data-cy="product-card"]').first().click();

    // Get product price from PDP
    const priceText = await page.locator('[data-cy="product-price"], text=$').first().textContent();
    const cleanPriceText = priceText ? priceText.replace('$', '').trim() : '0';
    const unitPrice = parseFloat(cleanPriceText);

    // Select quantity '2'
    const quantitySelect = page.locator('select[data-cy="product-quantity"]').first();
    await quantitySelect.selectOption({ label: '2' });

    // Click Add To Cart
    await page.locator('[data-cy="product-add-to-cart"]').click();

    // Verify we redirected to the Cart page
    await expect(page).toHaveURL(/\/cart/);

    // Verify subtotal matches unitPrice * 2
    const expectedSubtotal = unitPrice * 2;

    // Find the elements displaying prices in the cart items list
    // The first price is unit price, the second is total for that item
    const cartPrices = page.locator('text=$');
    const priceCount = await cartPrices.count();
    expect(priceCount).toBeGreaterThanOrEqual(1);

    // Click "Empty Cart" to check empty cart UI state
    const emptyCartBtn = page.locator('button:has-text("Empty Cart")');
    await expect(emptyCartBtn).toBeVisible();
    await emptyCartBtn.click();

    // Verify cart is now empty
    // The storefront should display an empty cart message
    await expect(page.locator('text=Your shopping cart is empty!')).toBeVisible();

    // The cart badge should be empty or show 0
    const cartBadge = page.locator('[data-cy="cart-item-count"]').first();
    await expect(cartBadge).not.toBeAttached(); // Badge element disappears when cart is empty
  });
});

import { test, expect } from '@playwright/test';

test.describe('E2E Checkout Flow', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to homepage
    await page.goto('/');
  });

  test('Should successfully checkout a product with valid billing and card details', async ({ page }) => {
    // 1. Browse and select the first product
    const firstProduct = page.locator('[data-cy="product-card"]').first();
    await expect(firstProduct).toBeVisible();
    await firstProduct.click();

    // 2. Add product to cart (which redirects to /cart)
    const addToCartBtn = page.locator('[data-cy="product-add-to-cart"]');
    await expect(addToCartBtn).toBeVisible();
    await addToCartBtn.click();

    // Verify redirect to /cart page
    await expect(page).toHaveURL(/\/cart/);

    // 3. Fill in the Checkout Form
    await page.fill('#email', 'engineering.manager@armorcode.com');
    await page.fill('#street_address', '100 Main Street');
    await page.fill('#zip_code', '95113');
    await page.fill('#city', 'San Jose');
    await page.fill('#state', 'CA');
    await page.fill('#country', 'United States');

    // Payment Details (Must use valid Luhn credit card matching Visa prefix '4')
    await page.fill('#credit_card_number', '4432-8015-6152-0454');

    // Select Expiration Month (e.g. August, option value '8')
    await page.selectOption('#credit_card_expiration_month', '8');

    // Dynamically calculate valid expiration year (current year + 2)
    const futureYear = (new Date().getFullYear() + 2).toString();
    await page.selectOption('#credit_card_expiration_year', futureYear);

    // Enter CVV
    await page.fill('#credit_card_cvv', '672');

    // 4. Submit Order
    const placeOrderBtn = page.locator('[data-cy="checkout-place-order"], button[type="submit"]:has-text("Place Order")');
    await expect(placeOrderBtn).toBeEnabled();
    await placeOrderBtn.click();

    // 5. Verify Checkout Confirmation screen is displayed
    // It should display complete message and have an order ID
    await expect(page.locator('text=Your order is complete!')).toBeVisible();

    // Verify that the Order ID is present on the confirmation screen
    const orderIdLabel = page.locator('text=Order ID:');
    await expect(orderIdLabel).toBeVisible();

    const orderIdText = await page.locator('h3:has-text("Order ID:") + p, text=/^[0-9a-fA-F-]+$/').first().textContent();
    console.log(`[CHECKOUT SUCCESS] Generated Order ID: ${orderIdText}`);
  });
});

